def layout(title, desc, page, body):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#191916"><meta name="description" content="{html.escape(desc)}"><title>{html.escape(title)} | FEALITY ITALY</title><link rel="stylesheet" href="css/site.css"></head><body data-page="{page}">{NAV}<main>{body}</main>{FOOT}</body></html>'''
def hero(kicker,title,sub,image,mark):
    return f'''<section class="hero"><div class="hero-media" style="background-image:url('{IMG}{image}')"></div><div class="container hero-content"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="hero-bottom">{sub}</p><a class="btn btn-light" href="#collection">Explore the collection <span>↘</span></a></div><span class="hero-mark">{mark}</span></section>'''
def form_section(interests='Kitchen, Wardrobe, Vanity, General enquiry'):
    opts=''.join(f'<option>{html.escape(x.strip())}</option>' for x in interests.split(','))
    return f'''<section class="section" id="enquiry"><div class="container form-wrap"><div class="form-intro"><p class="eyebrow">LET’S BEGIN WITH A CONVERSATION</p><h2 class="display">A considered space<br><em>starts here.</em></h2><p>Tell us about your room, priorities and preferred finish. The team can follow up with product information and next steps.</p><div class="tag">Project consultation</div><div class="tag">Material discussion</div><div class="tag">Customisation enquiry</div></div><form class="lead-form" data-lead-form><div class="field"><label for="lead-name">YOUR NAME *</label><input id="lead-name" name="name" autocomplete="name" required placeholder="Full name"></div><div class="field"><label for="lead-phone">PHONE / WHATSAPP *</label><input id="lead-phone" name="contact" autocomplete="tel" required placeholder="Your contact number"></div><div class="field"><label for="lead-interest">I AM INTERESTED IN</label><select id="lead-interest" name="interest">{opts}</select></div><div class="field"><label for="lead-city">CITY</label><input id="lead-city" name="city" placeholder="Your city"></div><div class="field full"><label for="lead-message">PROJECT DETAILS</label><textarea id="lead-message" name="message" placeholder="Room size, design preference, product model or questions..."></textarea></div><div class="field full"><button class="btn" type="submit">Prepare my enquiry ↗</button></div><p class="form-status" aria-live="polite">Enquiries are handed off through the verified WhatsApp number or email configured by the business. No details are sent to a server unless a lead endpoint is configured.</p></form></div></section>'''
